(5933835, 865139, 82999, '<td valign="top">Looks like an everyday studio shot.  Well done, but sort of ordinary.</td>', 'Looks like an everyday studio shot.  Well done, but sort of ordinary.', '2010-04-06 17:51:59.000000', NULL, 1),
(5933836, 864872, 75585, '<td valign="top">Hmmm yummy!!  His skin looks a bit blue hued - but I truly love the chocolate dripping off his chin :-)</td>', 'Hmmm yummy!!  His skin looks a bit blue hued - but I truly love the chocolate dripping off his chin :-)', '2010-04-06 17:52:32.000000', NULL, 1),
(5933837, 864781, 75585, '<td valign="top">This is absolutely precious.  Seems a bit small.  I think rotating is and having it in portrait orientation would have been nice - including the cute little belly button :-)</td>', 'This is absolutely precious.  Seems a bit small.  I think rotating is and having it in portrait orientation would have been nice - including the cute little belly button :-)', '2010-04-06 17:53:32.000000', NULL, 1),
(5933842, 865092, 75585, '<td valign="top">This is a bit dark on my monitor (but didn''t affect my vote) - a very precious photo and expect to see it on the front page.  Even the pink/purple sky cooperated with you.</td>', 'This is a bit dark on my monitor (but didn''t affect my vote) - a very precious photo and expect to see it on the front page.  Even the pink/purple sky cooperated with you.', '2010-04-06 17:55:29.000000', NULL, 1),
(5933845, 865043, 75585, '<td valign="top">Nice perspective on this - I don''t care for the vignette on it, but it is still a nice photo - check out those lashes!!!</td>', 'Nice perspective on this - I don''t care for the vignette on it, but it is still a nice photo - check out those lashes!!!', '2010-04-06 17:56:19.000000', NULL, 1),
(5933846, 864702, 75585, '<td valign="top">I really like the eyes peering out from the darkness.  What a wonderful shot.  Nicely executed!!</td>', 'I really like the eyes peering out from the darkness.  What a wonderful shot.  Nicely executed!!', '2010-04-06 17:56:54.000000', NULL, 1),
(5933847, 864757, 75585, '<td valign="top">Seems a little orange - the counter in the background being tilted is distracting for me.  I would try leveling that out and cropping a bit off the right so he is not so centered.</td>', 'Seems a little orange - the counter in the background being tilted is distracting for me.  I would try leveling that out and cropping a bit off the right so he is not so centered.', '2010-04-06 17:58:13.000000', NULL, 1),
(5933849, 865142, 75585, '<td valign="top">For me this is lacking contact with the subject - it feels like the doll in the house is more focal than the little girl.  I love her cute little bouncy curls!</td>', 'For me this is lacking contact with the subject - it feels like the doll in the house is more focal than the little girl.  I love her cute little bouncy curls!', '2010-04-06 17:59:49.000000', NULL, 1),
(5933852, 865162, 75585, '<td valign="top">What a handsome young man.  The detail on his shirt is a bit blown but I love his gaze and hat!  Reminds me of my oldest - he too is a serious one.</td>', 'What a handsome young man.  The detail on his shirt is a bit blown but I love his gaze and hat!  Reminds me of my oldest - he too is a serious one.', '2010-04-06 18:00:40.000000', NULL, 1),
(5933855, 865040, 75585, '<td valign="top">What a wonderful shot - she is so serious!</td>', 'What a wonderful shot - she is so serious!', '2010-04-06 18:01:30.000000', NULL, 1),
(5933982, 865042, 100831, '<td valign="top">love it!</td>', 'love it!', '2010-04-06 19:29:47.000000', NULL, 1),
(5933986, 865184, 100831, '<td valign="top">great shot - and it looks like we were celebrating more than Easter here!!</td>', 'great shot - and it looks like we were celebrating more than Easter here!!', '2010-04-06 19:33:03.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5933987, 865178, 100831, '<td valign="top">this is not a child. I won''t vote though.</td>', 'this is not a child. I won''t vote though.', '2010-04-06 19:33:09.000000', NULL, 1),
(5934140, 865178, 33769, '<td valign="top">LOVE the out of the box thinking- a child of the earth- a child of another flower...  :-) lovely image</td>', 'LOVE the out of the box thinking- a child of the earth- a child of another flower...  :-) lovely image', '2010-04-06 21:54:27.000000', NULL, 1),
(5934152, 864910, 33769, '<td valign="top">I love the expression - and i think in just black and white it would be a lovely image- or...if there was perhaps at ouch more color to balance it / eyes - rosey cheeks or even some tone to the skin desaturated to draw the eye back up- but instead my eye keeps going to his shirt instead of focusing and remaining on his adorable face :-)</td>', 'I love the expression - and i think in just black and white it would be a lovely image- or...if there was perhaps at ouch more color to balance it / eyes - rosey cheeks or even some tone to the skin desaturated to draw the eye back up- but instead my eye keeps going to his shirt instead of focusing and remaining on his adorable face :-)', '2010-04-06 21:58:22.000000', NULL, 1),
(5934160, 865089, 33769, '<td valign="top">interesting perspective/composition-  cant really see what is going on with the subject tho his body-language is indicating he is pulling something out of or dropping something into the water? i wish i could see better what he is doing perhaps a different angle? or a rule of 3rds crop might help? my eye keeps going to the blury stick to the right - behind his head...  then to his plaid underwear sticking out of his jeans - yep boys will be boys...</td>', 'interesting perspective/composition-  cant really see what is going on with the subject tho his body-language is indicating he is pulling something out of or dropping something into the water? i wish i could see better what he is doing perhaps a different angle? or a rule of 3rds crop might help? my eye keeps going to the blury stick to the right - behind his head...  then to his plaid underwear sticking out of his jeans - yep boys will be boys...', '2010-04-06 22:01:53.000000', NULL, 1),
(5934163, 864863, 33769, '<td valign="top">this is a nice c rop- there are some lovely colors in the image, i wish it was more in focus, and perhaps dodged and burned a bit more (the blown out leaves at the bottom under the child draws my eye down and off the page- away from him, the great tree- angle in the pic keeps my eye from wandering off uptop... but maybe taking advantage of the advanced editing option to sharpen would help? :-)</td>', 'this is a nice c rop- there are some lovely colors in the image, i wish it was more in focus, and perhaps dodged and burned a bit more (the blown out leaves at the bottom under the child draws my eye down and off the page- away from him, the great tree- angle in the pic keeps my eye from wandering off uptop... but maybe taking advantage of the advanced editing option to sharpen would help? :-)', '2010-04-06 22:04:12.000000', NULL, 1),
(5934165, 865162, 33769, '<td valign="top">interesting choice of saturation/desaturation/ editing- it really fits the i mage and the  flowers-  i wish the shirt wasnt so blown out but I can also see how it might add to the photo- by not taking up too much attention that way... i like the almost drawn effect of the image-- it could potentially be a greeting-card :-)</td>', 'interesting choice of saturation/desaturation/ editing- it really fits the i mage and the  flowers-  i wish the shirt wasnt so blown out but I can also see how it might add to the photo- by not taking up too much attention that way... i like the almost drawn effect of the image-- it could potentially be a greeting-card :-)', '2010-04-06 22:06:09.000000', NULL, 1),
(5934194, 865097, 43191, '<td valign="top">coming back to comment. I love this one, it is one of my 2 10''s. I love the mid step pose. The dress colour and hair colour are perfect with the suroundings. The green egg, blades of grass and green on the shoes just balance this out nicely. Over all a great image :)</td>', 'coming back to comment. I love this one, it is one of my 2 10''s. I love the mid step pose. The dress colour and hair colour are perfect with the suroundings. The green egg, blades of grass and green on the shoes just balance this out nicely. Over all a great image :)', '2010-04-06 22:24:59.000000', NULL, 1),
(5934198, 865187, 43191, '<td valign="top">Coming back to comment. This is one of my 2 10''s. I just love the pose, the cheeky smile and the outfit all work together to make an adorable portrait. Focus is perfect. You can really see this little fellow''s character shining through.</td>', 'Coming back to comment. This is one of my 2 10''s. I just love the pose, the cheeky smile and the outfit all work together to make an adorable portrait. Focus is perfect. You can really see this little fellow''s character shining through.', '2010-04-06 22:26:55.000000', NULL, 1),
(5934202, 864705, 43191, '<td valign="top">wonderful processing. I love the highlights in the blonde hair. A natural fun shot. It helps to have such beautiful children! Wonderful :)</td>', 'wonderful processing. I love the highlights in the blonde hair. A natural fun shot. It helps to have such beautiful children! Wonderful :)', '2010-04-06 22:28:18.000000', NULL, 1),
(5934205, 864781, 43191, '<td valign="top">Just stunning. I love the negative space and the pinkness of the shot. It looks like it was lit with sunlight which adds to the beauty of the image.I love the contrast of the chunky wool with the silky smooth skin of the baby. An adorable portrait :)</td>', 'Just stunning. I love the negative space and the pinkness of the shot. It looks like it was lit with sunlight which adds to the beauty of the image.I love the contrast of the chunky wool with the silky smooth skin of the baby. An adorable portrait :)', '2010-04-06 22:30:32.000000', NULL, 1),
(5934209, 865104, 43191, '<td valign="top">What a great fun shot! That firey hair and cute freckles give this shot a lot of charcter.  The cheeky smile and the twinkle in the eyes is a winner. I like the close cropping and the angle of the shot.</td>', 'What a great fun shot! That firey hair and cute freckles give this shot a lot of charcter.  The cheeky smile and the twinkle in the eyes is a winner. I like the close cropping and the angle of the shot.', '2010-04-06 22:32:41.000000', NULL, 1),
(5934211, 865153, 43191, '<td valign="top">Great composition. I love how the hair gets longer as the line progresses as well as the height increasing. The fact that they are all in blue works really well. A wonderful natural shot that tells a story. :)</td>', 'Great composition. I love how the hair gets longer as the line progresses as well as the height increasing. The fact that they are all in blue works really well. A wonderful natural shot that tells a story. :)', '2010-04-06 22:35:20.000000', NULL, 1),
(5934215, 864968, 43191, '<td valign="top">How adorable is he???!! I love this! The simplisity of it is wonderful. His expresion is priceless. He looks as if he is on a mission, too busy to stop for such inconvieniences as photographs. :)</td>', 'How adorable is he???!! I love this! The simplisity of it is wonderful. His expresion is priceless. He looks as if he is on a mission, too busy to stop for such inconvieniences as photographs. :)', '2010-04-06 22:37:16.000000', NULL, 1),
