(5936248, 864926, 69246, '<td valign="top">Hi, I work for DCF and....just kidding....fabulous shot</td>', 'Hi, I work for DCF and....just kidding....fabulous shot', '2010-04-07 21:09:41.000000', NULL, 1),
(5936250, 865105, 69246, '<td valign="top">perfect and beautiful</td>', 'perfect and beautiful', '2010-04-07 21:09:44.000000', NULL, 1),
(5936257, 865051, 69246, '<td valign="top">I like the composition, but, I''m not sure if I''m fond of the sepia tone. Egg hunts, Easter, speak colors, which is lost here. Otherwise, I like the shot.</td>', 'I like the composition, but, I''m not sure if I''m fond of the sepia tone. Egg hunts, Easter, speak colors, which is lost here. Otherwise, I like the shot.', '2010-04-07 21:12:23.000000', NULL, 1),
(5936259, 865176, 69246, '<td valign="top">I like the natural framing. The foreground and trees could have had a bit more lightness to them as it seems to draw the kids out of the photo, rather than have them as a part of the environment</td>', 'I like the natural framing. The foreground and trees could have had a bit more lightness to them as it seems to draw the kids out of the photo, rather than have them as a part of the environment', '2010-04-07 21:13:57.000000', NULL, 1),
(5936261, 865149, 69246, '<td valign="top">Compositionally, its a little busy with the angle and the background, especially the chair and the hutch. I''m not sure if the BW conversion works well. Egg coloring is colorful, so I''m not sure what is gained by the conversion.</td>', 'Compositionally, its a little busy with the angle and the background, especially the chair and the hutch. I''m not sure if the BW conversion works well. Egg coloring is colorful, so I''m not sure what is gained by the conversion.', '2010-04-07 21:15:48.000000', NULL, 1),
(5936266, 865153, 69246, '<td valign="top">Very nicely done. The composition really works here and I like the way you isolated the children with DOF. The young one is out of focus, but that is still ok because one would expect the past to be "blurry".</td>', 'Very nicely done. The composition really works here and I like the way you isolated the children with DOF. The young one is out of focus, but that is still ok because one would expect the past to be "blurry".', '2010-04-07 21:18:49.000000', NULL, 1),
(5936306, 864707, 100253, '<td valign="top">Beautiful use of spot color.</td>', 'Beautiful use of spot color.', '2010-04-07 21:41:05.000000', NULL, 1),
(5936314, 865136, 37845, '<td valign="top">Awesome perspective in this shot. Not sure if it was intentional, but the shoes form the shape of a heart.</td>', 'Awesome perspective in this shot. Not sure if it was intentional, but the shoes form the shape of a heart.', '2010-04-07 21:48:26.000000', NULL, 1),
(5936316, 864703, 37845, '<td valign="top">Amazing candid. I like how you were able to get some of the blurred foreground in the shot, give the photo a nice journalistic feel.</td>', 'Amazing candid. I like how you were able to get some of the blurred foreground in the shot, give the photo a nice journalistic feel.', '2010-04-07 21:49:15.000000', NULL, 1),
(5936317, 864950, 37845, '<td valign="top">Her gaze is intense. She looks like she is deep in thought, solving all the worlds problems while going on a light stroll. Beautiful photo.</td>', 'Her gaze is intense. She looks like she is deep in thought, solving all the worlds problems while going on a light stroll. Beautiful photo.', '2010-04-07 21:50:02.000000', NULL, 1),
