(5940163, 864968, 116570, '<td valign="top">The adult pretension on the kid''s face is captured well. Very artistic and simple. Not over-edited. A photograph captured real sense.</td>', 'The adult pretension on the kid''s face is captured well. Very artistic and simple. Not over-edited. A photograph captured real sense.', '2010-04-11 11:56:04.000000', NULL, 1),
(5940164, 864703, 116570, '<td valign="top">Captures a real moment and expression. The semi-transparent and out of focus foreground makes it impressive.</td>', 'Captures a real moment and expression. The semi-transparent and out of focus foreground makes it impressive.', '2010-04-11 11:58:54.000000', NULL, 1),
